"""Shared input schemas, output serialization, and tool-call diagnostics."""

from __future__ import annotations

import asyncio
import functools
import inspect
import json
import os
import time
from datetime import UTC, datetime
from pathlib import Path
from typing import Any, Callable, TypeVar, cast

from pydantic import BaseModel, ConfigDict, Field

from utils.request_context import request_account_id
from utils.settings import get_settings

F = TypeVar("F", bound=Callable[..., Any])


class ToolInput(BaseModel):
    """Reject undeclared tool arguments generated by a model."""

    model_config = ConfigDict(extra="forbid")


class PrioritizedToolInput(ToolInput):
    """Top-level tool schema with required execution-order metadata."""

    priority: int = Field(
        ge=1,
        description=(
            "Required positive integer for execution order; 1 runs first. "
            "When calling multiple tools together, each priority must be unique."
        ),
    )


def serialize_tool_output(value: Any) -> str:
    """Serialize JSON-compatible tool output compactly while preserving Unicode."""
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def _json_default(value: Any) -> Any:
    model_dump = getattr(value, "model_dump", None)
    if callable(model_dump):
        return model_dump(mode="json")
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return repr(value)


def _append_tool_io_record(record: dict[str, Any]) -> None:
    path = Path(get_settings().agent_tool_io_log_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = (json.dumps(record, ensure_ascii=False, default=_json_default) + "\n").encode()
    descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
    try:
        os.write(descriptor, payload)
    finally:
        os.close(descriptor)


def capture_tool_io(function: F) -> F:
    """Record tool arguments, result or exception, duration, and request identity."""
    signature = inspect.signature(function)
    name = function.__name__

    def make_record(
        started: datetime,
        began: float,
        arguments: dict[str, Any],
        output: Any,
        error: BaseException | None,
    ) -> dict[str, Any]:
        account_id = request_account_id.get(None)
        return {
            "timestamp": started.isoformat(),
            "duration_ms": round((time.perf_counter() - began) * 1000, 3),
            "tool": name,
            "caller": {"request_account_id": account_id},
            "inputs": arguments,
            "output": output if error is None else None,
            "error": None
            if error is None
            else {"type": type(error).__name__, "message": str(error)},
        }

    def arguments_for(args: tuple[Any, ...], kwargs: dict[str, Any]) -> dict[str, Any]:
        forwarded_kwargs = kwargs
        if "priority" not in signature.parameters:
            forwarded_kwargs = {key: value for key, value in kwargs.items() if key != "priority"}
        try:
            arguments = dict(signature.bind_partial(*args, **forwarded_kwargs).arguments)
            if "priority" in kwargs:
                arguments["priority"] = kwargs["priority"]
            return arguments
        except TypeError:
            return {"args": args, "kwargs": kwargs}

    def write(record: dict[str, Any]) -> None:
        try:
            _append_tool_io_record(record)
        except OSError:
            # A debug log must never change the result or failure of a tool call.
            pass

    if inspect.iscoroutinefunction(function):

        @functools.wraps(function)
        async def async_wrapper(*args: Any, **kwargs: Any) -> Any:
            started, began = datetime.now(UTC), time.perf_counter()
            arguments = arguments_for(args, kwargs)
            output = None
            error = None
            try:
                forwarded_kwargs = kwargs
                if "priority" not in signature.parameters:
                    forwarded_kwargs = {
                        key: value for key, value in kwargs.items() if key != "priority"
                    }
                output = await function(*args, **forwarded_kwargs)
                return output
            except BaseException as exc:
                error = exc
                raise
            finally:
                record = make_record(started, began, arguments, output, error)
                await asyncio.to_thread(write, record)

        return cast(F, async_wrapper)

    @functools.wraps(function)
    def sync_wrapper(*args: Any, **kwargs: Any) -> Any:
        started, began = datetime.now(UTC), time.perf_counter()
        arguments = arguments_for(args, kwargs)
        output = None
        error = None
        try:
            forwarded_kwargs = kwargs
            if "priority" not in signature.parameters:
                forwarded_kwargs = {
                    key: value for key, value in kwargs.items() if key != "priority"
                }
            output = function(*args, **forwarded_kwargs)
            return output
        except BaseException as exc:
            error = exc
            raise
        finally:
            write(make_record(started, began, arguments, output, error))

    return cast(F, sync_wrapper)
